for r in select * from jsonb_to_recordset($json$[{"key": "t08-z-lesotundra", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) Эта зона узкой полосой протягивается на севере Евразии и Северной Америки между двумя другими природными зонами.\n2) Лето короткое и прохладное (средняя температура июля +10…+12 °С), зима долгая и суровая.\n3) Участки с редкими низкорослыми деревьями (ель, лиственница, берёза) чередуются с участками мхов, лишайников и кустарничков.\n4) Почвы тундровые глеевые и подзолистые, местами встречается многолетняя мерзлота.\n5) Обитают северные олени, песцы, белые куропатки, лемминги; с юга заходят лоси и бурые медведи.", "answer": "лесотундра", "accepted": ["лесотундра", "лесотундры", "зона лесотундры", "лесотундровая зона"], "short": "Деревья растут, но редкие и низкорослые, и чередуются с тундрой — это переходная зона между тундрой и тайгой, лесотундра.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «тундра» или «тайга»: в тундре деревьев нет, в тайге лес сплошной. Здесь редколесье вперемешку с тундрой.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t08-z-polupustyni", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) Эта зона расположена между степями и пустынями; в Евразии она занимает Прикаспийскую низменность и часть Казахстана и Монголии.\n2) Климат резко континентальный, осадков выпадает 150–300 мм в год, а испариться может во много раз больше.\n3) Растительный покров разреженный: полынь, солянки, ковыль; между растениями видны участки голой почвы.\n4) Почвы светло-каштановые и бурые, часто засолённые.\n5) Обитают суслики, тушканчики, сайгаки, много змей и ящериц.", "answer": "полупустыни", "accepted": ["полупустыни", "полупустыня", "зона полупустынь", "полупустыни умеренного пояса"], "short": "Растительность ещё есть, но не смыкается, почвы каштановые и бурые, сухо — это переход от степи к пустыне, полупустыня.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «степь» (там сплошной травяной покров и чернозёмы) или «пустыня» (там растения очень редкие, почвы пустынные).", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t08-z-peremenno-vlazhnye", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) Эта зона распространена на полуостровах Индостан и Индокитай, а также в Африке и Южной Америке по окраинам экваториальных лесов.\n2) Температура высокая весь год; влажный летний сезон с ливнями сменяется сухим сезоном.\n3) Деревья в сухой сезон сбрасывают листья; растут тик, сандаловое дерево, бамбук.\n4) Почвы красные и красно-жёлтые ферраллитные.\n5) Обитают слоны, тигры, леопарды, обезьяны, павлины.", "answer": "переменно-влажные леса", "accepted": ["переменно-влажные леса", "переменно-влажные (в том числе муссонные) леса", "муссонные леса", "переменно-влажные и муссонные леса", "переменно-влажный лес", "муссонный лес"], "short": "Жарко весь год, но есть сухой сезон, и деревья на это время сбрасывают листья — это переменно-влажные (муссонные) леса.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «влажные экваториальные леса»: там сухого сезона нет и леса вечнозелёные. Или «саванны»: там трава с редкими деревьями, а здесь лес.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t08-z-shirokolistvennye", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) Эта зона распространена в Западной и Центральной Европе, на востоке Северной Америки и в Восточной Азии.\n2) Климат умеренный, зима мягкая, лето тёплое, увлажнение достаточное.\n3) Растут дуб, бук, клён, липа, ясень; деревья на зиму сбрасывают листву, травяной покров богатый.\n4) Почвы бурые лесные и серые лесные, богатые перегноем.\n5) Обитают олени, кабаны, барсуки, белки; в Европе сохранились зубры.", "answer": "широколиственные леса", "accepted": ["широколиственные леса", "широколиственный лес", "зона широколиственных лесов", "листопадные широколиственные леса", "смешанные и широколиственные леса"], "short": "Умеренный пояс, мягкая зима, лес из дуба, бука, клёна и липы без хвойных — это широколиственные леса.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «смешанные леса»: там вместе с лиственными растут хвойные (ель, сосна). Здесь хвойных нет.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t08-z-zhestkolistnye", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) Эта зона распространена на побережьях Средиземного моря, на юге Калифорнии, в центральном Чили, на юге Африки и юго-западе Австралии.\n2) Климат субтропический: лето жаркое и сухое, зима тёплая и дождливая.\n3) Растения вечнозелёные, с жёсткими кожистыми листьями: пробковый и каменный дуб, маслина, лавр, мирт, кипарис.\n4) Почвы коричневые.\n5) Обитают черепахи, ящерицы, змеи, горные козлы, много птиц.", "answer": "жестколистные вечнозелёные леса и кустарники", "accepted": ["жестколистные вечнозелёные леса и кустарники", "жестколистные вечнозеленые леса и кустарники", "жестколистные леса и кустарники", "жестколистные леса", "жестколистные вечнозелёные леса", "жестколистные вечнозеленые леса", "средиземноморские леса и кустарники"], "short": "Сухое жаркое лето и дождливая тёплая зима (средиземноморский климат), вечнозелёные растения с жёсткими листьями — жестколистные вечнозелёные леса и кустарники.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «субтропические леса» или «вечнозелёные леса» без главного слова: зона называется жестколистными вечнозелёными лесами и кустарниками.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t08-z-arkt-pustyni", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) Эта зона занимает острова Северного Ледовитого океана и север Гренландии.\n2) Зимой длится полярная ночь, лето короткое и холодное: средняя температура июля около 0 °С; осадков мало.\n3) Большая часть поверхности покрыта ледниками; на свободных от льда участках растут мхи, лишайники, полярный мак.\n4) Почвы маломощные, почти не развиты.\n5) Обитают белые медведи, моржи, тюлени; летом на скалах гнездятся птичьи базары.", "answer": "арктические пустыни", "accepted": ["арктические пустыни", "арктическая пустыня", "зона арктических пустынь", "ледяные пустыни", "арктические ледяные пустыни"], "short": "Самая северная зона: ледники, летом около 0 °С, только мхи и лишайники, белые медведи и моржи — арктические пустыни.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «тундра»: в тундре лето теплее (+5…+10 °С), есть кустарнички и карликовые берёзы, ледников нет.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t08-z-trop-pustyni", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) Самые обширные пространства эта зона занимает в Северной Африке, на Аравийском полуострове и в центральной части Австралии.\n2) Лето очень жаркое, велики суточные колебания температуры; осадков выпадает меньше 200 мм в год, а местами годами не бывает дождей.\n3) Растения редкие: колючие кустарники, акации, суккуленты; после редких дождей быстро появляются и отцветают травы.\n4) Почвы пустынные, малоплодородные; много песков и каменистых пространств.\n5) Обитают тушканчики, лисички фенеки, ящерицы, змеи, скорпионы; в Австралии — кенгуру и собака динго.", "answer": "тропические пустыни", "accepted": ["тропические пустыни", "тропическая пустыня", "пустыни", "пустыня", "пустыни тропического пояса", "тропические пустыни и полупустыни", "пустыни и полупустыни"], "short": "Тропический пояс, очень жарко и сухо (меньше 200 мм осадков), растений почти нет — тропические пустыни.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «саванны»: там есть влажный сезон и сплошной травяной покров. Или «полупустыни» — это зона умеренного пояса.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t08-z-smeshannye", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) В Евразии эта зона протягивается по Восточно-Европейской равнине между тайгой и широколиственными лесами и встречается на Дальнем Востоке; в Северной Америке — в районе Великих озёр.\n2) Климат умеренный: зима холодная, со снежным покровом, лето тёплое; осадков выпадает больше, чем может испариться.\n3) Хвойные деревья (ель, сосна, пихта) растут вместе с лиственными (дуб, липа, клён, берёза, осина).\n4) Почвы дерново-подзолистые.\n5) Обитают лоси, кабаны, косули, рыси, бурые медведи, белки, лисицы.", "answer": "смешанные леса", "accepted": ["смешанные леса", "смешанный лес", "зона смешанных лесов", "смешанные и широколиственные леса", "хвойно-широколиственные леса"], "short": "Ель и сосна растут вместе с дубом, липой и клёном, почвы дерново-подзолистые — это смешанные леса.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «тайга» (там почти одни хвойные, почвы подзолистые) или «широколиственные леса» (там нет хвойных).", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t08-z-lesostep", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) Эта зона протягивается полосой между лесами и степями; в Евразии — от Карпат до Алтая, есть она и в Северной Америке.\n2) Климат умеренный, лето тёплое; осадков выпадает примерно столько, сколько может испариться.\n3) Участки лиственных лесов (дуб, берёза, осина) чередуются с участками разнотравных степей.\n4) Под лесом формируются серые лесные почвы, под степью — чернозёмы.\n5) Обитают лоси и косули, зайцы, лисицы, а также суслики и сурки.", "answer": "лесостепь", "accepted": ["лесостепь", "лесостепи", "зона лесостепей", "лесостепная зона"], "short": "Леса чередуются со степными участками, под лесом серые почвы, под степью чернозёмы — это переходная зона, лесостепь.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «степь»: в степи деревьев почти нет. Или «смешанные леса»: там лес сплошной, степных участков нет.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t08-z-pustyni-umer", "task": 8, "type": "input_text_short", "template": "vpr7-08-natural-zone", "text": "Определите, какой природной зоне мира соответствуют приведённые ниже характеристики. Укажите в ответе название этой природной зоны.\n1) Эта зона занимает внутренние районы Евразии (Каракумы, Кызылкум, Гоби) и Северной Америки.\n2) Климат резко континентальный: лето жаркое и сухое, зима холодная, с морозами; осадков меньше 200 мм в год.\n3) Растительность редкая: саксаул, полынь, солянки, верблюжья колючка; весной ненадолго зацветают тюльпаны и другие эфемеры.\n4) Почвы серо-бурые, много солончаков и песков.\n5) Обитают верблюды, джейраны, тушканчики, песчанки, змеи, ящерицы.", "answer": "пустыни умеренного пояса", "accepted": ["пустыни умеренного пояса", "пустыни", "пустыня", "умеренные пустыни", "пустыни умеренного климатического пояса", "пустыни и полупустыни умеренного пояса"], "short": "Очень сухо (меньше 200 мм), но зима холодная с морозами — значит, это не тропики, а пустыни умеренного пояса.", "alg": "1. Прочитай пункт про климат: пояс (арктический, умеренный, субтропический, тропический, субэкваториальный, экваториальный) и увлажнение.\n2. Сверь растительность и почвы — они подсказывают зону точнее всего.\n3. Проверь по животным и распространению. Запиши название зоны.", "mistakes": "Пишут «тропические пустыни»: в тропических пустынях зимы тёплые, морозов почти не бывает. Или «полупустыни»: там растительность гуще, почвы каштановые.", "difficulty": 2, "kind": "text_short", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.14", "topics2": [], "batch": "b1"}, {"key": "t10-z01", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) смена направления бризов в течение суток\n2) смена природных зон на Восточно-Европейской равнине при движении с севера на юг\n3) понижение температуры воздуха с высотой\n4) осенний листопад в смешанных лесах", "answer": "2", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: смена природных зон на Восточно-Европейской равнине при движении с севера на юг.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-z02", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) смена климатических поясов при движении от экватора к Северному полюсу\n2) весеннее половодье на реках\n3) уменьшение плотности воздуха с высотой\n4) смена дня и ночи", "answer": "1", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: смена климатических поясов при движении от экватора к Северному полюсу.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-z03", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) смена направления муссонов по сезонам года\n2) смена высотных поясов в горах Кавказа\n3) морские приливы и отливы\n4) уменьшение разнообразия видов растений и животных в направлении от экватора к полюсам", "answer": "4", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: уменьшение разнообразия видов растений и животных в направлении от экватора к полюсам.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-z04", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) понижение атмосферного давления с высотой\n2) суточные колебания температуры воздуха\n3) смена природных зон в Африке при движении от экватора на север и на юг\n4) замерзание рек зимой", "answer": "3", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: смена природных зон в Африке при движении от экватора на север и на юг.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-z05", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) зимняя спячка медведей\n2) уменьшение высоты полуденного Солнца над горизонтом 21 марта при движении от экватора к полюсам\n3) изменение состава растительности в горах с высотой\n4) смена времён года в умеренных широтах", "answer": "2", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: уменьшение высоты полуденного Солнца над горизонтом 21 марта при движении от экватора к полюсам.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-z06", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) землетрясения на границах литосферных плит\n2) смена направления бризов в течение суток\n3) понижение температуры воздуха с высотой\n4) смена основных типов почв на Западно-Сибирской равнине при движении с севера на юг", "answer": "4", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: смена основных типов почв на Западно-Сибирской равнине при движении с севера на юг.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-z07", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) уменьшение количества солнечного тепла, получаемого земной поверхностью за год, при движении от экватора к полюсам\n2) перелёты птиц на юг осенью\n3) уменьшение плотности воздуха с высотой\n4) морские приливы и отливы", "answer": "1", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: уменьшение количества солнечного тепла, получаемого земной поверхностью за год, при движении от экватора к полюсам.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-z08", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) смена дня и ночи\n2) извержения вулканов\n3) увеличение продолжительности залегания снежного покрова при движении с юга на север по Восточно-Европейской равнине\n4) смена высотных поясов в Андах", "answer": "3", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: увеличение продолжительности залегания снежного покрова при движении с юга на север по Восточно-Европейской равнине.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-z09", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) смена направления муссонов по сезонам года\n2) увеличение продолжительности полярного дня при движении от Северного полярного круга к Северному полюсу\n3) понижение атмосферного давления с высотой\n4) весеннее половодье на реках", "answer": "2", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: увеличение продолжительности полярного дня при движении от Северного полярного круга к Северному полюсу.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-z10", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Зональность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) осенний листопад в широколиственных лесах\n2) понижение температуры воздуха с высотой\n3) суточные колебания температуры воздуха\n4) понижение среднегодовой температуры воздуха при движении от Каира к Санкт-Петербургу", "answer": "4", "accepted": null, "short": "Зональность — это закономерное изменение природы по географической широте, от экватора к полюсам: меняется количество солнечного тепла, а вслед за ним климат, почвы, растительность. Здесь по широте меняется только одно явление: понижение среднегодовой температуры воздуха при движении от Каира к Санкт-Петербургу.", "alg": "1. Ищи явление, которое меняется в пространстве по широте: «от экватора к полюсам», «с севера на юг».\n2. Отбрось изменения во времени (сутки, сезоны) — это ритмичность.\n3. Отбрось изменения с высотой — это высотная поясность, а не зональность.", "mistakes": "Путают зональность с высотной поясностью: изменения «с высотой» — это не зональность. И с ритмичностью: смена сезонов, бризов, муссонов происходит во времени, а не по широте.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-r11", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Ритмичность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) смена природных зон при движении от экватора к полюсам\n2) понижение температуры воздуха с высотой\n3) смена дня и ночи\n4) уменьшение плотности воздуха с высотой", "answer": "3", "accepted": null, "short": "Ритмичность — это повторение природных явлений через равные промежутки времени (сутки, год). Повторяется во времени здесь только одно явление: смена дня и ночи.", "alg": "1. Ищи явление, которое повторяется во времени: каждые сутки, каждый год, каждый сезон.\n2. Отбрось изменения по широте («от экватора к полюсам») — это зональность.\n3. Отбрось изменения с высотой — это не ритмичность.", "mistakes": "Выбирают смену природных зон: она происходит в пространстве (по широте), а не во времени. Изменения с высотой тоже не повторяются во времени.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-r12", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Ритмичность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) зимняя спячка медведей и ежей\n2) смена климатических поясов от экватора к полюсам\n3) смена высотных поясов в Гималаях\n4) землетрясения на границах литосферных плит", "answer": "1", "accepted": null, "short": "Ритмичность — это повторение природных явлений через равные промежутки времени (сутки, год). Повторяется во времени здесь только одно явление: зимняя спячка медведей и ежей.", "alg": "1. Ищи явление, которое повторяется во времени: каждые сутки, каждый год, каждый сезон.\n2. Отбрось изменения по широте («от экватора к полюсам») — это зональность.\n3. Отбрось изменения с высотой — это не ритмичность.", "mistakes": "Выбирают смену природных зон: она происходит в пространстве (по широте), а не во времени. Изменения с высотой тоже не повторяются во времени.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-r13", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Ритмичность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географических явлений является примером её проявления?\n1) понижение атмосферного давления с высотой\n2) смена основных типов почв с севера на юг\n3) извержения вулканов\n4) весеннее половодье на реках Восточно-Европейской равнины", "answer": "4", "accepted": null, "short": "Ритмичность — это повторение природных явлений через равные промежутки времени (сутки, год). Повторяется во времени здесь только одно явление: весеннее половодье на реках Восточно-Европейской равнины.", "alg": "1. Ищи явление, которое повторяется во времени: каждые сутки, каждый год, каждый сезон.\n2. Отбрось изменения по широте («от экватора к полюсам») — это зональность.\n3. Отбрось изменения с высотой — это не ритмичность.", "mistakes": "Выбирают смену природных зон: она происходит в пространстве (по широте), а не во времени. Изменения с высотой тоже не повторяются во времени.", "difficulty": 2, "kind": "single_number", "rubric": null, "max_score": 1, "image": null, "topic": "2.7.1", "topics2": ["2.7.14"], "batch": "b1"}, {"key": "t10-r14", "task": 10, "type": "input_number", "template": "vpr7-10-shell-property", "text": "Ритмичность – одна из важнейших закономерностей, свойственных географической оболочке. Какое из перечисленных географичес